use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut keys: Vec<int> = []
    let mut lefts: Vec<int> = []
    let mut rights: Vec<int> = []
    let mut root: int = -1
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0]
        if cmd == "insert" {
            let x: int = parts[1].parse::<int>().unwrap_or(0)
            if root == -1 {
                keys.push(x)
                lefts.push(-1)
                rights.push(-1)
                root = 0
                println("ok")
                continue
            }
            let mut cur: int = root
            let mut done = false
            while !done {
                let k = keys[cur as usize]
                if x == k {
                    println("dup")
                    done = true
                } else if x < k {
                    let l = lefts[cur as usize]
                    if l == -1 {
                        let n: int = keys.len() as int
                        keys.push(x)
                        lefts.push(-1)
                        rights.push(-1)
                        lefts[cur as usize] = n
                        println("ok")
                        done = true
                    } else {
                        cur = l
                    }
                } else {
                    let r = rights[cur as usize]
                    if r == -1 {
                        let n: int = keys.len() as int
                        keys.push(x)
                        lefts.push(-1)
                        rights.push(-1)
                        rights[cur as usize] = n
                        println("ok")
                        done = true
                    } else {
                        cur = r
                    }
                }
            }
        } else if cmd == "contains" {
            let x: int = parts[1].parse::<int>().unwrap_or(0)
            let mut cur: int = root
            let mut found = false
            while cur != -1 && !found {
                let k = keys[cur as usize]
                if x == k {
                    found = true
                } else if x < k {
                    cur = lefts[cur as usize]
                } else {
                    cur = rights[cur as usize]
                }
            }
            if found { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            let x: int = parts[1].parse::<int>().unwrap_or(0)
            let mut cur: int = root
            let mut parent: int = -1
            let mut isleft = false
            let mut found = false
            while cur != -1 && !found {
                let k = keys[cur as usize]
                if x == k {
                    found = true
                } else if x < k {
                    parent = cur
                    isleft = true
                    cur = lefts[cur as usize]
                } else {
                    parent = cur
                    isleft = false
                    cur = rights[cur as usize]
                }
            }
            if !found {
                println("missing")
            } else {
                let l = lefts[cur as usize]
                let r = rights[cur as usize]
                if l != -1 && r != -1 {
                    let mut sp: int = cur
                    let mut s: int = r
                    while lefts[s as usize] != -1 {
                        sp = s
                        s = lefts[s as usize]
                    }
                    keys[cur as usize] = keys[s as usize]
                    if sp == cur {
                        rights[cur as usize] = rights[s as usize]
                    } else {
                        lefts[sp as usize] = rights[s as usize]
                    }
                } else {
                    let child: int = if l != -1 { l } else { r }
                    if parent == -1 {
                        root = child
                    } else if isleft {
                        lefts[parent as usize] = child
                    } else {
                        rights[parent as usize] = child
                    }
                }
                println("ok")
            }
        } else if cmd == "inorder" {
            if root == -1 {
                println("<empty>")
            } else {
                let mut stack: Vec<int> = []
                let mut out: Vec<string> = []
                let mut cur: int = root
                while cur != -1 || stack.len() > 0 {
                    while cur != -1 {
                        stack.push(cur)
                        cur = lefts[cur as usize]
                    }
                    let n = stack.pop().unwrap_or(0)
                    out.push("${keys[n as usize]}")
                    cur = rights[n as usize]
                }
                println(out.join(" "))
            }
        } else if cmd == "height" {
            let mut best: int = 0
            if root != -1 {
                let mut ns: Vec<int> = [root]
                let mut ds: Vec<int> = [1]
                while ns.len() > 0 {
                    let n = ns.pop().unwrap_or(0)
                    let d = ds.pop().unwrap_or(0)
                    if d > best { best = d }
                    if lefts[n as usize] != -1 {
                        ns.push(lefts[n as usize])
                        ds.push(d + 1)
                    }
                    if rights[n as usize] != -1 {
                        ns.push(rights[n as usize])
                        ds.push(d + 1)
                    }
                }
            }
            println("${best}")
        } else if cmd == "min" {
            if root == -1 {
                println("empty")
            } else {
                let mut cur: int = root
                while lefts[cur as usize] != -1 {
                    cur = lefts[cur as usize]
                }
                println("${keys[cur as usize]}")
            }
        } else if cmd == "max" {
            if root == -1 {
                println("empty")
            } else {
                let mut cur: int = root
                while rights[cur as usize] != -1 {
                    cur = rights[cur as usize]
                }
                println("${keys[cur as usize]}")
            }
        }
    }
}

